-- Lost Kingsland Admin V7.1 - 90 equipment-specific crafting ores + resource media contract
-- 9 craft slots x 10 rarities. Includes PET. Idempotent; safe after V7.0.
BEGIN;
CREATE SCHEMA IF NOT EXISTS admin;
-- Enrich the 10 existing economy assets with display/icon hints without changing balances.
UPDATE economy.asset_defs SET metadata=COALESCE(metadata,'{}'::jsonb) || '{"display_name_vi": "Vàng", "icon_hint": "shiny-purse", "static_media": true}'::jsonb WHERE code='GOLD';
UPDATE economy.asset_defs SET metadata=COALESCE(metadata,'{}'::jsonb) || '{"display_name_vi": "Ngọc", "icon_hint": "gems", "static_media": true}'::jsonb WHERE code='GEMS';
UPDATE economy.asset_defs SET metadata=COALESCE(metadata,'{}'::jsonb) || '{"display_name_vi": "Gỗ", "icon_hint": "log", "static_media": true}'::jsonb WHERE code='WOOD';
UPDATE economy.asset_defs SET metadata=COALESCE(metadata,'{}'::jsonb) || '{"display_name_vi": "Quặng", "icon_hint": "ore", "static_media": true}'::jsonb WHERE code='ORE';
UPDATE economy.asset_defs SET metadata=COALESCE(metadata,'{}'::jsonb) || '{"display_name_vi": "Lương thực", "icon_hint": "wheat", "static_media": true}'::jsonb WHERE code='FOOD';
UPDATE economy.asset_defs SET metadata=COALESCE(metadata,'{}'::jsonb) || '{"display_name_vi": "Tinh hoa", "icon_hint": "concentration-orb", "static_media": true}'::jsonb WHERE code='ESSENCE';
UPDATE economy.asset_defs SET metadata=COALESCE(metadata,'{}'::jsonb) || '{"display_name_vi": "Linh khí", "icon_hint": "aura", "static_media": true}'::jsonb WHERE code='CULTIVATION_QI';
UPDATE economy.asset_defs SET metadata=COALESCE(metadata,'{}'::jsonb) || '{"display_name_vi": "Điểm kỹ năng", "icon_hint": "upgrade", "static_media": true}'::jsonb WHERE code='SKILL_POINT';
UPDATE economy.asset_defs SET metadata=COALESCE(metadata,'{}'::jsonb) || '{"display_name_vi": "Dấu ấn Clan", "icon_hint": "shield", "static_media": true}'::jsonb WHERE code='CLAN_MARKS';
UPDATE economy.asset_defs SET metadata=COALESCE(metadata,'{}'::jsonb) || '{"display_name_vi": "Token Mùa", "icon_hint": "token", "static_media": true}'::jsonb WHERE code='SEASON_TOKEN';

-- Seed exactly 90 equipment crafting ores: 9 craft slots x 10 rarities.
ON CONFLICT(code) DO UPDATE SET asset_type='CRAFT_MATERIAL', integrity_tier='B', precision_scale=0, transferable=false, metadata=COALESCE(economy.asset_defs.metadata,'{}'::jsonb) || EXCLUDED.metadata;

CREATE OR REPLACE VIEW admin.v_crafting_ore_materials AS
SELECT a.code, a.asset_type,
       a.metadata->>'display_name_vi' AS display_name_vi,
       a.metadata->>'target_slot' AS target_slot,
       a.metadata->>'target_rarity' AS target_rarity,
       COALESCE((a.metadata->>'active')::boolean,true) AS active,
       NULLIF(a.metadata->>'image_asset_key','') AS image_asset_key,
       a.metadata->>'purpose_vi' AS purpose_vi,
       COALESCE((a.metadata->>'rarity_ordinal')::int,0) AS rarity_ordinal,
       COALESCE((a.metadata->>'slot_ordinal')::int,0) AS slot_ordinal,
       COALESCE((a.metadata->>'demo_craft_cost')::int,20) AS demo_craft_cost,
       l.asset_key AS linked_primary_asset_key
FROM economy.asset_defs a
LEFT JOIN LATERAL (SELECT asset_key FROM platform.entity_media_links x WHERE x.entity_type='ECONOMY_ASSET' AND x.entity_id=a.code AND x.is_primary=true ORDER BY x.created_at DESC LIMIT 1) l ON true
WHERE a.metadata->>'material_family'='EQUIPMENT_ORE'
ORDER BY COALESCE((a.metadata->>'rarity_ordinal')::int,0), COALESCE((a.metadata->>'slot_ordinal')::int,0);

CREATE OR REPLACE VIEW admin.v_static_economy_assets AS
SELECT a.code,a.asset_type,a.metadata->>'display_name_vi' AS display_name_vi, NULLIF(a.metadata->>'image_asset_key','') AS image_asset_key, l.asset_key AS linked_primary_asset_key, a.metadata
FROM economy.asset_defs a
LEFT JOIN LATERAL (SELECT asset_key FROM platform.entity_media_links x WHERE x.entity_type='ECONOMY_ASSET' AND x.entity_id=a.code AND x.is_primary=true ORDER BY x.created_at DESC LIMIT 1) l ON true
WHERE a.code IN ('GOLD','GEMS','WOOD','ORE','FOOD','ESSENCE','CULTIVATION_QI','SKILL_POINT','CLAN_MARKS','SEASON_TOKEN')
ORDER BY CASE a.code WHEN 'GOLD' THEN 1 WHEN 'GEMS' THEN 2 WHEN 'WOOD' THEN 3 WHEN 'ORE' THEN 4 WHEN 'FOOD' THEN 5 WHEN 'ESSENCE' THEN 6 WHEN 'CULTIVATION_QI' THEN 7 WHEN 'SKILL_POINT' THEN 8 WHEN 'CLAN_MARKS' THEN 9 WHEN 'SEASON_TOKEN' THEN 10 ELSE 99 END;

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='lk_admin_readonly') THEN
    GRANT SELECT ON admin.v_crafting_ore_materials, admin.v_static_economy_assets TO lk_admin_readonly;
    GRANT SELECT ON economy.asset_defs TO lk_admin_readonly;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='lk_admin_config_editor') THEN
    GRANT SELECT,INSERT,UPDATE ON economy.asset_defs TO lk_admin_config_editor;
    GRANT SELECT ON admin.v_crafting_ore_materials, admin.v_static_economy_assets TO lk_admin_config_editor;
    GRANT SELECT,INSERT,UPDATE,DELETE ON platform.media_assets, platform.entity_media_links TO lk_admin_config_editor;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname='lost_kingsland_admin') THEN
    GRANT SELECT,INSERT,UPDATE ON economy.asset_defs TO lost_kingsland_admin;
    GRANT SELECT ON admin.v_crafting_ore_materials, admin.v_static_economy_assets TO lost_kingsland_admin;
    GRANT SELECT,INSERT,UPDATE,DELETE ON platform.media_assets, platform.entity_media_links TO lost_kingsland_admin;
  END IF;
END $$;

COMMIT;
